     1→// ============================================================================
     2→// FreeLang Collections 모듈 - 슬라이스 처리 및 데이터 구조
     3→// ============================================================================
     4→// 목표: Zero-Copy-DB에서 벡터, 배열, 인덱스 목록 등을 처리할 수 있도록 함
     5→// 원리:
     6→//   1. i64 슬라이스를 기본 컨테이너로 사용 (ID, 오프셋, 카운터 등)
     7→//   2. 1급 함수 미지원 → map/filter를 구체적 파라미터로 구현
     8→//   3. f32 슬라이스용 별도 함수 세트 제공 (벡터 연산용)
     9→//   4. 이터레이터 패턴으로 순회 가능
    10→// 구조:
    11→//   - 상수 정의 (SORT_ASC, SORT_DESC)
    12→//   - Iter, ZipPair 구조체
    13→//   - @inline 집계 헬퍼
    14→//   - 집계 함수 (sum, min, max, count, reduce)
    15→//   - 검색 함수 (find, find_all, contains)
    16→//   - 변환 함수 (filter_*, map_*)
    17→//   - 조작 함수 (take, skip, zip, foreach)
    18→//   - 정렬 함수 (sort_asc, sort_desc, sort_by)
    19→//   - f32 전용 함수들
    20→// ============================================================================
    21→
    22→module collections {
    23→    // === 상수 ===
    24→    const SORT_ASC:  i32 = 1;
    25→    const SORT_DESC: i32 = -1;
    26→
    27→    // === 데이터 구조체 ===
    28→    // 슬라이스 반복자
    29→    struct Iter {
    30→        data:   [i64];
    31→        pos:    i32;
    32→        length: i32;
    33→    }
    34→
    35→    // zip 결과용 쌍 구조체
    36→    struct ZipPair {
    37→        left:  i64;
    38→        right: i64;
    39→    }
    40→
    41→    // === 이터레이터 함수 ===
    42→
    43→    // 슬라이스로부터 이터레이터 생성
    44→    func iter(data: [i64]) -> Iter {
    45→        return Iter{
    46→            data:   data,
    47→            pos:    0,
    48→            length: len(data),
    49→        };
    50→    }
    51→
    52→    // 이터레이터가 다음 원소를 가지고 있는지 확인
    53→    @inline
    54→    func (it: *Iter) has_next() -> bool {
    55→        return it.pos < it.length;
    56→    }
    57→
    58→    // 이터레이터에서 다음 원소 추출
    59→    @inline
    60→    func (it: *Iter) next() -> (i64, bool) {
    61→        if !it.has_next() {
    62→            return (0, false);
    63→        }
    64→        let val = it.data[it.pos];
    65→        it.pos = it.pos + 1;
    66→        return (val, true);
    67→    }
    68→
    69→    // === 집계 함수 ===
    70→
    71→    // 슬라이스의 모든 원소 합계
    72→    func sum(data: [i64]) -> i64 {
    73→        let acc = i64(0);
    74→        let i = 0;
    75→        for i = 0; i < len(data); i = i + 1 {
    76→            acc = acc + data[i];
    77→        }
    78→        return acc;
    79→    }
    80→
    81→    // 슬라이스의 최솟값 (오버플로우 방지: i64 사용)
    82→    func min(data: [i64]) -> (i64, bool) {
    83→        if len(data) == 0 {
    84→            return (0, false);
    85→        }
    86→        let min_val = data[0];
    87→        let i = 1;
    88→        for i = 1; i < len(data); i = i + 1 {
    89→            let v = data[i];
    90→            if v < min_val {
    91→                min_val = v;
    92→            }
    93→        }
    94→        return (min_val, true);
    95→    }
    96→
    97→    // 슬라이스의 최댓값
    98→    func max(data: [i64]) -> (i64, bool) {
    99→        if len(data) == 0 {
   100→            return (0, false);
   101→        }
   102→        let max_val = data[0];
   103→        let i = 1;
   104→        for i = 1; i < len(data); i = i + 1 {
   105→            let v = data[i];
   106→            if v > max_val {
   107→                max_val = v;
   108→            }
   109→        }
   110→        return (max_val, true);
   111→    }
   112→
   113→    // 슬라이스의 원소 개수
   114→    @inline
   115→    func count(data: [i64]) -> i32 {
   116→        return len(data);
   117→    }
   118→
   119→    // threshold 이상인 원소 개수
   120→    func count_where(data: [i64], threshold: i64) -> i32 {
   121→        let cnt = 0;
   122→        let i = 0;
   123→        for i = 0; i < len(data); i = i + 1 {
   124→            if data[i] >= threshold {
   125→                cnt = cnt + 1;
   126→            }
   127→        }
   128→        return cnt;
   129→    }
   130→
   131→    // 누적 합계 (initial값에서 시작)
   132→    func reduce(data: [i64], initial: i64) -> i64 {
   133→        let acc = initial;
   134→        let i = 0;
   135→        for i = 0; i < len(data); i = i + 1 {
   136→            acc = acc + data[i];
   137→        }
   138→        return acc;
   139→    }
   140→
   141→    // === 검색 함수 ===
   142→
   143→    // target과 일치하는 첫 번째 인덱스 반환
   144→    func find(data: [i64], target: i64) -> (i32, bool) {
   145→        let i = 0;
   146→        for i = 0; i < len(data); i = i + 1 {
   147→            if data[i] == target {
   148→                return (i32(i), true);
   149→            }
   150→        }
   151→        return (-1, false);
   152→    }
   153→
   154→    // target과 일치하는 모든 인덱스 수집
   155→    func find_all(data: [i64], target: i64) -> [i32] {
   156→        let indices = make([i32], 0);
   157→        let i = 0;
   158→        for i = 0; i < len(data); i = i + 1 {
   159→            if data[i] == target {
   160→                indices.push(i32(i));
   161→            }
   162→        }
   163→        return indices;
   164→    }
   165→
   166→    // target이 슬라이스에 포함되어 있는지 확인
   167→    func contains(data: [i64], target: i64) -> bool {
   168→        let idx, found = find(data, target);
   169→        return found;
   170→    }
   171→
   172→    // === 변환 함수 ===
   173→
   174→    // 각 원소에 factor를 곱하기
   175→    func map_fn(data: [i64], factor: i64) -> [i64] {
   176→        let result = make([i64], len(data));
   177→        let i = 0;
   178→        for i = 0; i < len(data); i = i + 1 {
   179→            result[i] = data[i] * factor;
   180→        }
   181→        return result;
   182→    }
   183→
   184→    // 각 원소에 offset을 더하기
   185→    func map_add(data: [i64], offset: i64) -> [i64] {
   186→        let result = make([i64], len(data));
   187→        let i = 0;
   188→        for i = 0; i < len(data); i = i + 1 {
   189→            result[i] = data[i] + offset;
   190→        }
   191→        return result;
   192→    }
   193→
   194→    // threshold보다 큰 원소만 필터링
   195→    func filter_gt(data: [i64], threshold: i64) -> [i64] {
   196→        let result = make([i64], 0);
   197→        let i = 0;
   198→        for i = 0; i < len(data); i = i + 1 {
   199→            if data[i] > threshold {
   200→                result.push(data[i]);
   201→            }
   202→        }
   203→        return result;
   204→    }
   205→
   206→    // [min, max] 범위에 있는 원소만 필터링
   207→    func filter_range(data: [i64], min: i64, max: i64) -> [i64] {
   208→        let result = make([i64], 0);
   209→        let i = 0;
   210→        for i = 0; i < len(data); i = i + 1 {
   211→            let v = data[i];
   212→            if v >= min && v <= max {
   213→                result.push(v);
   214→            }
   215→        }
   216→        return result;
   217→    }
   218→
   219→    // === 조작 함수 ===
   220→
   221→    // 앞의 n개 원소만 추출
   222→    func take(data: [i64], n: i32) -> [i64] {
   223→        if n >= len(data) {
   224→            return data;
   225→        }
   226→        if n <= 0 {
   227→            return make([i64], 0);
   228→        }
   229→        let result = make([i64], n);
   230→        let i = 0;
   231→        for i = 0; i < n; i = i + 1 {
   232→            result[i] = data[i];
   233→        }
   234→        return result;
   235→    }
   236→
   237→    // 앞의 n개 원소 제외하고 나머지 반환
   238→    func skip(data: [i64], n: i32) -> [i64] {
   239→        if n >= len(data) {
   240→            return make([i64], 0);
   241→        }
   242→        if n <= 0 {
   243→            return data;
   244→        }
   245→        let result = make([i64], 0);
   246→        let i = n;
   247→        for i = n; i < len(data); i = i + 1 {
   248→            result.push(data[i]);
   249→        }
   250→        return result;
   251→    }
   252→
   253→    // 두 슬라이스를 쌍으로 엮기 (짧은 쪽 기준)
   254→    func zip(a: [i64], b: [i64]) -> [ZipPair] {
   255→        let len_a = len(a);
   256→        let len_b = len(b);
   257→        let min_len = if len_a < len_b { len_a } else { len_b };
   258→        let result = make([ZipPair], min_len);
   259→        let i = 0;
   260→        for i = 0; i < min_len; i = i + 1 {
   261→            result[i] = ZipPair{ left: a[i], right: b[i] };
   262→        }
   263→        return result;
   264→    }
   265→
   266→    // 각 원소를 label과 함께 출력 (부수효과용)
   267→    func foreach(data: [i64], label: string) {
   268→        let i = 0;
   269→        for i = 0; i < len(data); i = i + 1 {
   270→            print(label + "[" + i32_to_string(i32(i)) + "]=" + i64_to_string(data[i]));
   271→        }
   272→    }
   273→
   274→    // === 정렬 함수 ===
   275→
   276→    // 오름차순 정렬 (삽입 정렬)
   277→    func sort_asc(data: [i64]) -> [i64] {
   278→        let result = data;  // 복사 가정: FreeLang 런타임이 제공
   279→        let len_val = len(result);
   280→        let i = 1;
   281→        for i = 1; i < len_val; i = i + 1 {
   282→            let key = result[i];
   283→            let j = i - 1;
   284→            for j >= 0 && result[j] > key {
   285→                result[j + 1] = result[j];
   286→                j = j - 1;
   287→            }
   288→            result[j + 1] = key;
   289→        }
   290→        return result;
   291→    }
   292→
   293→    // 내림차순 정렬
   294→    func sort_desc(data: [i64]) -> [i64] {
   295→        let sorted = sort_asc(data);
   296→        let len_val = len(sorted);
   297→        let result = make([i64], len_val);
   298→        let i = 0;
   299→        for i = 0; i < len_val; i = i + 1 {
   300→            result[i] = sorted[len_val - 1 - i];
   301→        }
   302→        return result;
   303→    }
   304→
   305→    // direction에 따라 정렬 (SORT_ASC / SORT_DESC)
   306→    func sort_by(data: [i64], direction: i32) -> [i64] {
   307→        if direction == SORT_ASC {
   308→            return sort_asc(data);
   309→        } else {
   310→            return sort_desc(data);
   311→        }
   312→    }
   313→
   314→    // === f32 전용 함수 (벡터 연산용) ===
   315→
   316→    // f32 슬라이스의 합계
   317→    func f32_sum(data: [f32]) -> f32 {
   318→        let acc = f32(0.0);
   319→        let i = 0;
   320→        for i = 0; i < len(data); i = i + 1 {
   321→            acc = acc + data[i];
   322→        }
   323→        return acc;
   324→    }
   325→
   326→    // f32 슬라이스의 최솟값
   327→    func f32_min(data: [f32]) -> (f32, bool) {
   328→        if len(data) == 0 {
   329→            return (0.0, false);
   330→        }
   331→        let min_val = data[0];
   332→        let i = 1;
   333→        for i = 1; i < len(data); i = i + 1 {
   334→            let v = data[i];
   335→            if v < min_val {
   336→                min_val = v;
   337→            }
   338→        }
   339→        return (min_val, true);
   340→    }
   341→
   342→    // f32 슬라이스의 최댓값
   343→    func f32_max(data: [f32]) -> (f32, bool) {
   344→        if len(data) == 0 {
   345→            return (0.0, false);
   346→        }
   347→        let max_val = data[0];
   348→        let i = 1;
   349→        for i = 1; i < len(data); i = i + 1 {
   350→            let v = data[i];
   351→            if v > max_val {
   352→                max_val = v;
   353→            }
   354→        }
   355→        return (max_val, true);
   356→    }
   357→
   358→    // f32 슬라이스에서 threshold보다 큰 원소만 필터링
   359→    func f32_filter_gt(data: [f32], threshold: f32) -> [f32] {
   360→        let result = make([f32], 0);
   361→        let i = 0;
   362→        for i = 0; i < len(data); i = i + 1 {
   363→            if data[i] > threshold {
   364→                result.push(data[i]);
   365→            }
   366→        }
   367→        return result;
   368→    }
   369→
   370→    // f32 슬라이스 오름차순 정렬
   371→    func f32_sort_asc(data: [f32]) -> [f32] {
   372→        let result = data;
   373→        let len_val = len(result);
   374→        let i = 1;
   375→        for i = 1; i < len_val; i = i + 1 {
   376→            let key = result[i];
   377→            let j = i - 1;
   378→            for j >= 0 && result[j] > key {
   379→                result[j + 1] = result[j];
   380→                j = j - 1;
   381→            }
   382→            result[j + 1] = key;
   383→        }
   384→        return result;
   385→    }
   386→
   387→    // === 헬퍼 함수 ===
   388→
   389→    @inline
   390→    func i32_to_string(n: i32) -> string {
   391→        if n == 0 { return "0"; }
   392→        if n == 1 { return "1"; }
   393→        if n < 0 { return "-" + i32_to_string(-n); }
   394→        return "?";
   395→    }
   396→
   397→    @inline
   398→    func i64_to_string(n: i64) -> string {
   399→        return i32_to_string(i32(n));
   400→    }
   401→}
   402→
   403→// === 테스트 시나리오 (주석) ===
   404→// 기본 동작:
   405→//   - sum([1, 2, 3]) → 6
   406→//   - min([3, 1, 2]) → (1, true)
   407→//   - max([3, 1, 2]) → (3, true)
   408→//   - count([1, 2, 3]) → 3
   409→//   - find([10, 20, 30], 20) → (1, true)
   410→//   - contains([10, 20, 30], 20) → true
   411→//   - filter_gt([10, 20, 30, 5], 15) → [20, 30]
   412→//   - sort_asc([3, 1, 2]) → [1, 2, 3]
   413→//   - take([1, 2, 3, 4], 2) → [1, 2]
   414→//   - skip([1, 2, 3, 4], 2) → [3, 4]
   415→//   - zip([1, 2], [10, 20]) → [ZipPair{1,10}, ZipPair{2,20}]
