    13→module data_insertion_test {
    14→    // === 테스트 상수 ===
    15→    const TEST_KEYS: i32 = 100;
    16→    const TEST_NODES: i32 = 3;
    17→
    18→    // === 테스트 유틸리티 ===
    19→
    20→    struct DataInsertionResult {
    21→        total_inserted:  i32;
    22→        total_failed:    i32;
    23→        total_reads:     i32;
    24→        successful_reads: i32;
    25→        avg_latency:     i32;
    26→    }
    27→
    28→    func result_new() -> DataInsertionResult {
    29→        return DataInsertionResult{
    30→            total_inserted:    0,
    31→            total_failed:      0,
    32→            total_reads:       0,
    33→            successful_reads:  0,
    34→            avg_latency:       0,
    35→        };
