    40→    // 테스트 키 생성: "key_0", "key_1", ..., "key_99"
    41→    func make_test_key(idx: i32) -> string {
    42→        return "key_" + i32_to_str(idx);
    43→    }
    44→
    45→    // 테스트 값 생성: idx * 1000 + checksum
    46→    func make_test_value(idx: i32) -> i64 {
    47→        let checksum = i64(idx % 10);
    48→        return i64(idx) * 1000 + checksum;
    49→    }
