    61→        for i = 0; i < TEST_KEYS; i = i + 1 {
    62→            let key = make_test_key(i);
    63→            let val = make_test_value(i);
    64→
    65→            // 쿼럼 쓰기 (현재 노드만 있으므로 quorum=1)
    66→            let node_copy = node;
    67→            node_copy.rep_group.nodes[0].state = replication.REPLICA_ALIVE;
