   278→        if n == 0 { return "0"; }
   279→        if n == 1 { return "1"; }
   280→        if n == 2 { return "2"; }
   281→        if n == 3 { return "3"; }
   282→        if n == 4 { return "4"; }
   283→        if n == 5 { return "5"; }
   284→        if n == 6 { return "6"; }
   285→        if n == 7 { return "7"; }
   286→        if n == 8 { return "8"; }
   287→        if n == 9 { return "9"; }
   288→        if n < 0 { return "-" + i32_to_str(-n); }
   289→        return "?";
