     2→// FreeLang RPC 모듈 - Channel 기반 네트워크 통신
     3→// ============================================================================
     4→// 목표: Zero-Copy-DB에서 분산 노드 간 원격 함수 호출(RPC)을 구현
     5→// 원리:
     6→//   1. concurrent.Channel을 양방향 파이프로 사용 (네트워크 시뮬레이션)
     7→//   2. 메시지는 전역 풀에 저장 후 인덱스를 i64로 전달
     8→//   3. 동기 호출: 응답 채널에서 max 100 tick 폴링
     9→//   4. 핸들러는 if체인 디스패치로 구현
    10→// 구조:
    11→//   - 상수 정의 (메시지 타입, 에러 코드)
    12→//   - Message, Transport, Client, Server 구조체
    13→//   - @inline 헬퍼
    14→//   - 팩토리 함수
    15→//   - Transport 파이프 (양방향 채널 쌍)
    16→//   - Client: 동기 호출, inflight 관리
    17→//   - Server: 핸들러 등록, 요청 디스패치
    18→// ============================================================================
    19→
    20→module rpc {
    21→    // === 상수: 메시지 타입 ===
    22→    const MSG_REQUEST:  i32 = 1;
    23→    const MSG_RESPONSE: i32 = 2;
    24→    const MSG_ERROR:    i32 = 3;
    25→    const MSG_PING:     i32 = 4;
    26→    const MSG_PONG:     i32 = 5;
    27→
    28→    // === 상수: 에러 코드 ===
    29→    const RPC_OK:             i32 = 0;
    30→    const RPC_ERR_NOT_FOUND:  i32 = 1;
    31→    const RPC_ERR_TIMEOUT:    i32 = 2;
    32→    const RPC_ERR_NO_HANDLER: i32 = 3;
    33→    const RPC_ERR_CLOSED:     i32 = 4;
    34→
    35→    // === 상수: 프로토콜 파라미터 ===
    36→    const PROTO_VERSION:  i32 = 1;
    37→    const MAX_INFLIGHT:   i32 = 64;
    38→    const MAX_METHODS:    i32 = 16;
    39→    const MAX_MESSAGES:   i32 = 256;
    40→    const RECV_TIMEOUT:   i32 = 100;   // tick 단위
    41→
    42→    // === 데이터 구조체 ===
    43→    // RPC 메시지 (20 바이트 헤더 시뮬레이션)
    44→    struct Message {
    45→        msg_type:   i32;        // MSG_REQUEST / MSG_RESPONSE / MSG_ERROR / MSG_PING / MSG_PONG
    46→        msg_id:     i64;        // 단조 증가 ID
    47→        method:     string;     // "kv.set", "kv.get", "ping", ...
    48→        payload:    i64;        // 직렬화된 페이로드 (i64로 단순화)
    49→        error_msg:  string;     // 에러 메시지 (비어있으면 성공)
    50→    }
    51→
    52→    // 네트워크 추상화 (채널 기반 양방향 파이프)
    53→    struct Transport {
    54→        send_ch:    concurrent.Channel;  // 송신 채널
    55→        recv_ch:    concurrent.Channel;  // 수신 채널
    56→        node_id:    string;
    57→        is_open:    bool;
    58→    }
    59→
